package com.ruoyi.framework.web.exception;

import java.util.*;
import org.springframework.validation.Errors;
import org.springframework.validation.FieldError;
import com.ruoyi.common.core.domain.AjaxResult;

/** Stable field paths and safe Chinese messages; never echo rejected values. */
public final class InputValidationErrors {
 private InputValidationErrors() {}
 private static final Map<String,String> LABELS=Map.ofEntries(
  Map.entry("productIds","关联产品"),Map.entry("description","介绍"),Map.entry("userName","用户名称"),Map.entry("roleKey","角色标识"),Map.entry("configName","参数名称"),Map.entry("configKey","参数键名"),Map.entry("configValue","参数键值"),Map.entry("dictName","字典名称"),Map.entry("dictType","字典类型"),Map.entry("dictLabel","字典标签"),Map.entry("dictValue","字典键值"),Map.entry("deptName","部门名称"),Map.entry("postName","岗位名称"),Map.entry("postCode","岗位编码"),Map.entry("menuName","菜单名称"),Map.entry("noticeTitle","公告标题"),Map.entry("sortOrder","排序"),Map.entry("deltaWeight","净重差额"),Map.entry("deltaQuantity","数量差额"),Map.entry("deltaGrossWeight","毛重差额"),Map.entry("deltaImpurity","杂质差额"),Map.entry("quantity","数量"),Map.entry("completedQuantity","实际完成数量"),Map.entry("plannedQuantity","批次计划数量"),Map.entry("customer","客户"),Map.entry("factoryId","工厂"),Map.entry("productionLineId","产线"),Map.entry("productionLineIds","关联产线"),Map.entry("warehouseId","仓库"),Map.entry("ownerId","负责人"),Map.entry("operatorIds","经办人"),Map.entry("operatorId","经办人"),Map.entry("keeperId","仓管员"),Map.entry("recipientId","领用人"),Map.entry("productId","产品"),Map.entry("processId","工序"),Map.entry("itemId","产品明细"),Map.entry("workOrderId","生产工单"),Map.entry("batchId","加工批次"),Map.entry("inventoryId","库存物料"),Map.entry("sourceLineId","来源出库明细"),Map.entry("referenceId","物料"),Map.entry("requestId","请求标识"),Map.entry("version","版本"),Map.entry("reason","原因"),Map.entry("remark","备注"),Map.entry("name","名称"),Map.entry("code","编号"),Map.entry("factoryName","工厂名称"),Map.entry("area","占地面积"),Map.entry("address","详细地址"),Map.entry("introduction","简介"),Map.entry("netWeight","实测净重"),Map.entry("grossWeight","毛重"),Map.entry("impurity","杂质"),Map.entry("purity","纯度"),Map.entry("weight","理论成品净重"),Map.entry("volume","体积"),Map.entry("loss","理论损耗"),Map.entry("tolerance","损耗容差"),Map.entry("basePrice","基础单价"),Map.entry("piValue","圆周率"),Map.entry("items","产品明细"),Map.entry("lines","物料明细"),Map.entry("plans","工序计划"),Map.entry("processes","加工工序"),Map.entry("dimensions","尺寸"),Map.entry("category","类别"),Map.entry("materialType","物料类型"),Map.entry("processType","工序类型"),Map.entry("phonenumber","手机号"),Map.entry("nickName","姓名"),Map.entry("roleName","角色名称"),Map.entry("roleIds","角色"),Map.entry("status","状态"),Map.entry("enabled","启用状态"),Map.entry("sourceSequence","来源工序"),Map.entry("targetSequence","目标工序"),Map.entry("orderDate","单据日期"),Map.entry("startTime","开始时间"),Map.entry("endTime","结束时间"),Map.entry("email","邮箱"),Map.entry("password","密码"),Map.entry("newPassword","新密码"),Map.entry("oldPassword","原密码"),Map.entry("organization","单位名称"),Map.entry("specification","规格型号"),Map.entry("purpose","用途"),Map.entry("batchNo","批次号"),Map.entry("receivingOrganization","收货单位"));
 public static String label(String field){String leaf=field.replaceAll("\\.<[^>]+>", "").replaceAll("\\[.*?\\]", "");leaf=leaf.substring(leaf.lastIndexOf('.')+1);return LABELS.getOrDefault(leaf,"输入项");}
 public static Map<String,String> field(String path,String code,String message){return Map.of("field",path,"code",code,"message",message);}
 public static AjaxResult response(List<Map<String,String>> fields){return AjaxResult.error(fields.isEmpty()?"输入内容不合法，请检查后重试":fields.get(0).get("message")).put("fieldErrors",fields);}
 public static AjaxResult from(Errors errors){var fields=new ArrayList<Map<String,String>>();for(var error:errors.getAllErrors()){String path=error instanceof FieldError f?f.getField():"";String code=Objects.toString(error.getCode(),"Invalid");Object[] args=error.getArguments();String message=error.getDefaultMessage();if(message==null||!message.matches(".*[\u4e00-\u9fff].*")){String hint=switch(code){case "NotBlank","NotNull","NotEmpty"->"不能为空";case "Size","Length"->"长度或条目数量不符合要求";case "Digits"->"整数位数或小数精度超出允许范围";case "Min","Max","DecimalMin","DecimalMax","Positive","PositiveOrZero","Negative","NegativeOrZero"->"超出允许范围";case "Email"->"格式不正确";case "Pattern"->"格式不符合要求";default->"格式或取值不合法";};message=label(path)+hint;if(args!=null){if(code.equals("Digits")&&args.length>=3)message=label(path)+"最多"+args[2]+"位整数、"+args[1]+"位小数";if((code.equals("Min")||code.equals("Max"))&&args.length>=2)message=label(path)+(code.equals("Min")?"不能小于":"不能大于")+args[1];if((code.equals("Size")||code.equals("Length"))&&args.length>=3)message=label(path)+"长度或条目数量须为"+args[2]+"～"+args[1];}}if(!message.contains(label(path)))message=label(path)+"："+message;fields.add(field(path,code,message));}return response(fields);}
}
